function findClickTarget(frame, matchers){
  // matchers: array of strings to search in node name/characters (case-insensitive contains)
  let found=null;
  function walk(n){
    if(found) return;
    if(n.type==='TEXT' && n.characters){
      for(const m of matchers){ if(n.characters.toLowerCase().includes(m.toLowerCase())){ found=n; return; } }
    }
    if('children' in n){ for(const c of n.children){ walk(c); if(found) return; } }
  }
  walk(frame);
  return found;
}

function setClick(node, targetFrame){
