function findAllTexts(frame, matcher){
  let found=[];
  function walk(n){
    if(n.type==='TEXT' && n.characters && n.characters.toLowerCase().includes(matcher.toLowerCase())){ found.push(n); }
    if('children' in n){ for(const c of n.children){ walk(c); } }
  }
  walk(frame);
  return found;
}
function setClick(node, targetFrame){
  node.reactions = [{
    actions:[{type:'NODE', destinationId: targetFrame.id, navigation:'NAVIGATE', transition:null, preserveScrollPosition:false}],
