let results=[];
function link(frameName, matcher, targetName, idx){
  const frame = byName[frameName]; const target = byName[targetName];
  if(!frame||!target){ results.push('MISSING '+frameName+'->'+targetName); return; }
  const found = findAllTexts(frame, matcher);
  const node = idx!=null ? found[idx] : found[0];
  if(!node){ results.push('NOTFOUND '+frameName+' "'+matcher+'"'); return; }
  setClick(node, target);
  results.push('OK '+frameName+' ['+node.characters+'] -> '+targetName);
}

