// tab bars: find TabBar frame's Chat/Visits/Home icon groups by name 'Home'/'Visits' etc as text labels
function linkTabBar(frameName, label, targetName){
  const frame=byName[frameName]; const target=byName[targetName];
  if(!frame||!target) { results.push('MISSING tab '+frameName); return; }
  const bar = frame.findOne(n=>n.name==='TabBar');
  if(!bar){ results.push('NO TABBAR '+frameName); return; }
  const t = bar.findOne(n=>n.type==='TEXT' && n.characters===label);
  if(!t){ results.push('NO LABEL '+label+' in '+frameName); return; }
  setClick(t, target);
  results.push('OK tabbar '+frameName+' '+label+' -> '+targetName);
}
